# https://sqlstring.readthedocs.io/en/latest/source/sqlstring_usage.html#SelectBuilder# pip install git+https://github.com/saun4app/sqlstring from sqlstring.sql_builder import SelectBuilderfrom sqlstring.sql_builder import InsertBuilderbuilder = SelectBuilder()builder.from_table('test').get_query_string()builder = SelectBuilder()builder.from_table('address').distinct().get_query_string()builder = SelectBuilder()builder.from_table('address').column(['city', 'state_code'])builder.get_query_string()builder = SelectBuilder()builder.from_table('address').where('state_code', '=', " 'CA' ")builder.where('city', '=', " 'Oakland' ", 'AND')builder.get_query_string()builder = SelectBuilder()builder.from_table('address').group_by(['state_code', 'city'])builder.get_query_string()builder = SelectBuilder()builder.from_table('address').order_by(['state_code', 'city'], 'DESC')builder.get_query_string()builder = SelectBuilder()builder.from_table('address').limit(100).offset(200).get_query_string()builder = SelectBuilder()builder.from_table('address').join_table('contact')builder.where('address.state_code', '=', " contact.state_code ")builder.get_query_string()